SELECT order_id, SUM(order_qty) AS total_order_qty, SUM(IFNULL(received_qty, 0)) AS total_received_qty FROM mis_purchase_order_detail WHERE order_id IN
#{id}
AND del_flag = '0' GROUP BY order_id

SELECT d.order_id, COALESCE(SUM(sid.apply_qty), 0) AS applied_qty FROM mis_purchase_order_detail d LEFT JOIN mis_stock_in_detail sid ON d.id = sid.source_detail_id LEFT JOIN mis_stock_in si ON sid.stock_in_id = si.id AND si.status = 'APPLY' AND si.del_flag = '0' AND si.source_order_type = 'PURCHASE' WHERE d.order_id IN
#{id}
AND d.del_flag = '0' GROUP BY d.order_id
